module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);

    // Intermediate wires for the two AND gate outputs
    wire and_out1;
    wire and_out2;

    // First layer: two AND gates
    and and_gate1 (and_out1, a, b);
    and and_gate2 (and_out2, c, d);

    // Second layer: OR gate combining AND outputs
    or or_gate (out, and_out1, and_out2);

    // Inverted output generated by NOT gate on 'out'
    not not_gate (out_n, out);

endmodule